fn test_tool() -> Tool {
    Tool {
        name: "double_number".into(),
        description: "Doubles a number and returns the result".into(),
        parameters: json!({
            "type": "object",
            "properties": {"value": {"type": "number", "description": "A number to double"}},
            "required": ["value"]
        }),
    }
}

fn user(text: &str) -> Message {
    Message::User(UserMessage {
        content: vec![Content::Text(TextContent::new(text))].into(),
        timestamp: 0,
    })
}

fn model_for(provider: &str, id: &str, api: Option<&str>) -> Option<Model> {
    let mut model = cortexcode_ai::models::get_model(provider, id)?.clone();
    if let Some(api) = api {
        model.api = api.into();
    }
    Some(model)
}

fn options(model: &Model, api_key: &str) -> SimpleStreamOptions {
    SimpleStreamOptions {
        api_key: Some(api_key.into()),
        reasoning: model.reasoning.then_some(ThinkingLevel::High),
        ..Default::default()
    }
}

fn complete(model: &Model, context: Context, api_key: &str) -> AssistantMessage {
    let runtime = tokio::runtime::Runtime::new().unwrap();
    let opts = options(model, api_key);
    runtime.block_on(async {
        match complete_simple(model.clone(), context, opts).await {
            Ok(m) => m,
            Err(e) => AssistantMessage {
                stop_reason: StopReason::Error,
                error_message: Some(e.to_string()),
                ..Default::default()
            },
        }
    })
}

/// `generateContext`: a real exchange with a tool call and its result.
fn generate_context(model: &Model, api_key: &str) -> Option<Vec<Message>> {
    let prompt = user("Please double the number 21 using the double_number tool.");
    let first = complete(
        model,
        Context::new(
            "You are a helpful assistant. Use the provided tool to complete the task.".into(),
            vec![prompt.clone()],
            vec![test_tool()],
        ),
        api_key,
    );
    if first.stop_reason == StopReason::Error {
        eprintln!("  Initial request error: {:?}", first.error_message);
        return None;
    }
    let Some(call) = first.content.iter().find_map(|c| match c {
        Content::ToolCall(tc) => Some(tc.clone()),
        _ => None,
    }) else {
        return Some(vec![prompt, Message::Assistant(first)]);
    };
    let result = Message::ToolResult(ToolResultMessage {
        tool_call_id: call.id.clone(),
        tool_name: call.name.clone(),
        content: vec![Content::Text(TextContent::new("42"))],
        details: None,
        is_error: false,
        timestamp: 0,
    });
    let messages = vec![prompt, Message::Assistant(first), result];
    let last = complete(
        model,
        Context::new(
            "You are a helpful assistant.".into(),
            messages.clone(),
            vec![test_tool()],
        ),
        api_key,
    );
    if last.stop_reason == StopReason::Error {
        eprintln!("  Final request error: {:?}", last.error_message);
        return None;
    }
    let mut messages = messages;
    messages.push(Message::Assistant(last));
    Some(messages)
}

#[test]
#[ignore = "live: needs provider API keys and network"]
fn cross_provider_handoff() {
    let mut contexts: Vec<(&str, Model, String, Vec<Message>)> = Vec::new();
    for (provider, id, label, api) in PROVIDER_MODEL_PAIRS {
        let Some(api_key) = cortexcode_ai::env::get_env_api_key(provider) else {
            eprintln!("[{label}] Skipping - no auth for {provider}");
            continue;
        };
        let Some(model) = model_for(provider, id, *api) else {
            eprintln!("[{label}] Model not found");
            continue;
        };
        eprintln!("[{label}] Generating fixture...");
        match generate_context(&model, &api_key) {
            Some(messages) if messages.len() >= 4 => {
                contexts.push((label, model, api_key, messages))
            }
            _ => eprintln!("[{label}] Failed to generate fixture, skipping"),
        }
    }
    assert!(
        contexts.len() >= 2,
        "need at least 2 fixtures, got {}",
        contexts.len()
    );

    let mut failures = Vec::new();
    for (label, model, api_key, _) in &contexts {
        let mut messages: Vec<Message> = contexts
            .iter()
            .filter(|(other, ..)| other != label)
            .flat_map(|(.., m)| m.clone())
            .collect();
        messages.push(user(
            "Great, thanks for all that help! Now just say 'Hello, handoff successful!' to confirm you received everything.",
        ));
        let response = complete(
            model,
            Context::new(
                "You are a helpful assistant.".into(),
                messages,
                vec![test_tool()],
            ),
            api_key,
        );
        if response.stop_reason == StopReason::Error {
            eprintln!("[Target: {label}] FAILED: {:?}", response.error_message);
            failures.push(format!("{label}: {:?}", response.error_message));
        } else {
            eprintln!("[Target: {label}] SUCCESS");
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
